INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('9e816128-a358-40a7-ae0f-8063a050e04f', 'a1b2c3d4-2222-4000-8000-000000000002', 2, 'Oração Vocal', 'As palavras que nos unem ao céu', '{"intro": "A ora\u00e7\u00e3o vocal \u00e9 a forma mais acess\u00edvel de rezar. O Pai Nosso, a Ave Maria, o Gl\u00f3ria \u2014 s\u00e3o ora\u00e7\u00f5es que Jesus e a Igreja nos ensinaram. Mas aten\u00e7\u00e3o: rezar vocalmente n\u00e3o \u00e9 repetir palavras vazias. Jesus alertou contra a \"v\u00e3 repeti\u00e7\u00e3o\" (Mt 6,7). A chave \u00e9 unir l\u00e1bios e cora\u00e7\u00e3o. Santo Agostinho dizia: \"Quem canta, reza duas vezes\". A ora\u00e7\u00e3o vocal \u00e9 porta de entrada para profundidades maiores.", "prayer": "Pai nosso que est\u00e1s nos c\u00e9us... ensina-me a dizer estas palavras n\u00e3o com os l\u00e1bios apenas, mas com toda a minha alma. Am\u00e9m.", "practice": "Reze o Pai Nosso cinco vezes, mas muito devagar. A cada frase, pare e reflita sobre o que est\u00e1 dizendo. Anote qual frase mais tocou seu cora\u00e7\u00e3o.", "scripture": "\"V\u00f3s, pois, orai assim: Pai nosso, que est\u00e1s nos c\u00e9us, santificado seja o teu nome...\" \u2014 Mt 6,9", "reflection": "Qual ora\u00e7\u00e3o vocal voc\u00ea mais reza? Consegue rez\u00e1-la devagar, sentindo cada palavra?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;